if(!exists('stress_pool_counterparties'))library(creditratingsystem)
scp_D<-'2023-01-01';scp_dates<-list('2023-02-01','2023-03-01','2023-04-01')
scp_fixture<-function(){contract<-list(contract_id='cp',version='1',scenario_ids=list('s'),weights=list(1),dates=scp_dates,currency='EUR',probability_measure='PHYSICAL',sampling_design='FIXED_WEIGHTED_SCENARIOS',conditioning='PIT');list(baseline_cashflows=list(list(scenario_id='s',cashflow_id='cash',date=scp_dates[[2]],amount=100)),exposure_contracts=list(list(exposure_id='account',counterparty_id='bank',netting_set_id='net',role='ACCOUNT_BANK',basis='CASH_HELD',cashflow_ids=list('cash'))),netting_sets=list(list(netting_set_id='net',counterparty_id='bank',enforceable=TRUE,collateral_contract_id='collateral',collateral_convention='RECEIVED_TRANSFERABLE',default_timing='AFTER_COLLATERAL_SNAPSHOT_BEFORE_CASHFLOWS')),exposure_paths=lapply(scp_dates,function(d)list(scenario_id='s',exposure_id='account',date=d,signed_replacement_mark=0)),collateral_paths=lapply(scp_dates,function(d)list(scenario_id='s',netting_set_id='net',date=d,known_at=d,collateral_value=20,haircut=.5)),settlement_terms=list(list(scenario_id='s',counterparty_id='bank',estate_recovery_fraction=.5,estate_capacity=1000,estate_delay_days=30,collateral_delay_days=0,replacement_cost=5,replacement_delay_days=0)),scenario_contract=contract,party_mapping=list(list(party_id='bank',default_group_id='bank')),party_default_paths=lapply(scp_dates,function(d)list(scenario_id='s',default_group_id='bank',date=d,conditional_pd=if(d==scp_dates[[1]])1 else 0,default_channel='bank')),shared_innovations=lapply(scp_dates,function(d)list(scenario_id='s',date=d,channel_id='bank',uniform=.5)),as_of=scp_D)}
scp_run<-function(f)do.call(stress_pool_counterparties,f)$value
scp_swap<-function(f,mark){f$exposure_contracts[[2]]<-list(exposure_id='swap',counterparty_id='bank',netting_set_id='net',role='SWAP',basis='REPLACEMENT',cashflow_ids=list());f$exposure_paths<-c(f$exposure_paths,lapply(scp_dates,function(d)list(scenario_id='s',exposure_id='swap',date=d,signed_replacement_mark=mark)));f}
scp_error<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}
r<-scp_run(scp_fixture());n<-r$netting_results[[1]];e<-r$ending_states[[1]];stopifnot(n$positive_exposure==100,n$collateral_recovery==10,n$estate_recovery==45,n$credit_loss==45,n$proportional_loss_by_role$ACCOUNT_BANK==45,e$adjusted_net_cash==50,e$additional_replacement_cost==5,e$conservation_residual==0,length(r$removed_baseline_cashflows)==1L,Filter(function(x)x$source=='ESTATE_RECOVERY',r$adjusted_cashflows)[[1]]$date=='2023-03-03')
r<-scp_run(scp_swap(scp_fixture(),-60));n<-r$netting_results[[1]];stopifnot(n$net_closeout==40,n$credit_loss==15,r$ending_states[[1]]$adjusted_net_cash==80);r<-scp_run(scp_swap(scp_fixture(),-150));n<-r$netting_results[[1]];stopifnot(n$net_closeout== -50,n$credit_loss==0,r$ending_states[[1]]$adjusted_net_cash==95,Filter(function(x)x$source=='NEGATIVE_NET_CLOSEOUT',r$adjusted_cashflows)[[1]]$amount== -50)
f<-scp_fixture();f$baseline_cashflows<-list();f$exposure_contracts<-list(list(exposure_id='account',counterparty_id='bank',netting_set_id='net',role='SWAP',basis='REPLACEMENT',cashflow_ids=list()));for(i in seq_along(f$exposure_paths))f$exposure_paths[[i]]$signed_replacement_mark<-100;r<-scp_run(f);e<-r$ending_states[[1]];stopifnot(e$baseline_cash==0,e$adjusted_net_cash== -50,e$credit_loss==45,e$conservation_residual==0)
f<-scp_fixture();f$baseline_cashflows[[2]]<-list(scenario_id='s',cashflow_id='other',date=scp_dates[[2]],amount=100);f$exposure_contracts[[2]]<-list(exposure_id='servicer',counterparty_id='bank',netting_set_id='second',role='SERVICER',basis='CASH_HELD',cashflow_ids=list('other'));n<-f$netting_sets[[1]];n$netting_set_id<-'second';n$collateral_contract_id<-'othercoll';f$netting_sets[[2]]<-n;extra<-f$exposure_paths;for(i in seq_along(extra))extra[[i]]$exposure_id<-'servicer';f$exposure_paths<-c(f$exposure_paths,extra);extra<-f$collateral_paths;for(i in seq_along(extra))extra[[i]]$netting_set_id<-'second';f$collateral_paths<-c(f$collateral_paths,extra);f$settlement_terms[[1]]$estate_capacity<-30;r<-scp_run(f);stopifnot(all(vapply(r$netting_results,function(x)x$estate_recovery==15,TRUE)),r$counterparty_results[[1]]$estate_recovery==30,r$ending_states[[1]]$additional_replacement_cost==5,r$ending_states[[1]]$credit_loss==150,r$ending_states[[1]]$adjusted_net_cash==45)
f<-scp_fixture();f$baseline_cashflows[[1]]$date<-scp_dates[[1]];stopifnot(scp_run(f)$ending_states[[1]]$credit_loss==45);f$baseline_cashflows[[1]]$date<-scp_D;r<-scp_run(f);stopifnot(length(r$removed_baseline_cashflows)==0L,r$ending_states[[1]]$credit_loss==0,r$ending_states[[1]]$adjusted_net_cash==95);f<-scp_fixture();f$party_default_paths[[1]]$conditional_pd<-0;r<-scp_run(f);stopifnot(r$ending_states[[1]]$adjusted_net_cash==100,r$ending_states[[1]]$additional_replacement_cost==0)
f<-scp_fixture();e<-f$exposure_contracts[[1]];e$exposure_id<-'duplicate';f$exposure_contracts[[2]]<-e;scp_error('STRUCTURED_DOUBLE_COUNT',scp_run(f));f<-scp_swap(scp_fixture(),-50);f$netting_sets[[1]]$enforceable<-FALSE;scp_error('STRUCTURED_NETTING',scp_run(f));f<-scp_fixture();f$collateral_paths[[1]]$known_at<-scp_dates[[2]];scp_error('STRUCTURED_COLLATERAL',scp_run(f));f<-scp_fixture();f$settlement_terms[[1]]$estate_delay_days<-1000;scp_error('STRUCTURED_UNRESOLVED',scp_run(f))
cat('Native netting/collateral, signed replacement and shared capacity oracles PASS\n')
